import { notFound } from 'next/navigation'
import { DetailHead } from '../../../components/ontology/detail-head'
import { ElementDetailTabs } from '../../../components/ontology/element-detail-tabs'
import { ElementTile } from '../../../components/ontology/element-tile'
import { PageFrame } from '../../../components/ontology/page-frame'
import { StatusBadge } from '../../../components/ontology/status-badge'
import { elements, findElement } from '../../../lib/demo-data'

export function generateStaticParams() {
  return elements.map((e) => ({ id: e.id }))
}

/** depth 상세: 뒤로 · 이전 · 다음, 세그먼트 탭. 목록의 줄을 누르면 이 화면으로 옵니다 */
export default async function EntityDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const element = findElement(id)
  if (!element) notFound()

  const index = elements.findIndex((e) => e.id === element.id)
  const prev = elements[index - 1]
  const next = elements[index + 1]

  return (
    <PageFrame>
      <DetailHead
        backHref="/entities"
        backLabel="요소 목록으로"
        title={element.name}
        subtitle={`${element.nameEn} · ${element.owner}`}
        lead={<ElementTile kind={element.kind} />}
        badges={<StatusBadge status={element.status} />}
        prevHref={prev ? `/entities/${prev.id}` : undefined}
        nextHref={next ? `/entities/${next.id}` : undefined}
      />
      <ElementDetailTabs element={element} />
    </PageFrame>
  )
}

import { Button } from '@axis-ds/ui-react/button'
import { EntityList } from '../../components/ontology/entity-list'
import { ListHead } from '../../components/ontology/list-head'
import { PageFrame } from '../../components/ontology/page-frame'
import { elements } from '../../lib/demo-data'

/** 목록 페이지: 메뉴의 첫 화면. 머리 · 도구줄(검색 + 필터 칩) · 표 */
export default function EntitiesPage() {
  return (
    <PageFrame>
      <ListHead
        title="요소 목록"
        count={elements.length}
        description="온톨로지를 이루는 엔티티 · 관계 · 로직 · 액션이에요. 줄을 누르면 상세로 가요."
        tools={<Button type="button">새 요소</Button>}
      />
      <EntityList />
    </PageFrame>
  )
}

/* AXIS 토큰: 기본 CSS 변수(--axis-*)와 shadcn 호환 변수(--background · --primary 등). @import 는 @tailwind 보다 앞에 둡니다 */
@import "@axis-ds/tokens/css";
@import "@axis-ds/tokens/css/shadcn";
/* ontology 브랜드: app/layout.tsx 의 <html data-brand="ontology"> 와 짝입니다. 끄려면 두 곳을 함께 지웁니다 */
@import "@axis-ds/tokens/css/brands/ontology";

@tailwind base;
@tailwind components;
@tailwind utilities;

/*
 * 테두리 기본색: Tailwind 3 preflight 의 `* { border-color: gray-200 }` 가 shadcn 호환 CSS 의 `* { border-color }` 보다
 * 뒤에 와서 이기므로, `border` 클래스가 다크 · 브랜드에서도 회색으로 남지 않게 AXIS --border 로 되돌립니다
 */
@layer base {
  * {
    @apply border-border;
  }
  body {
    word-break: keep-all;
    overflow-wrap: break-word;
  }
}

import type { Metadata } from 'next'
import { ThemeProvider } from '@axis-ds/theme'
// AXIS 대표 글꼴 Pretendard(동적 서브셋). 글꼴 스택은 AXIS preset 이 <html> 에 적용합니다
import 'pretendard/dist/web/variable/pretendardvariable-dynamic-subset.css'
import './globals.css'
import { AppShell } from '../components/ontology/app-shell'

export const metadata: Metadata = {
  title: 'Ontology Console',
  description: 'AXIS ontology 브랜드 기반 업무 콘솔',
}

/**
 * 브랜드를 두 곳에서 켭니다.
 * - <html data-brand="ontology">: 서버 HTML 부터 브랜드 색으로 그려 첫 화면이 바뀌지 않습니다
 * - ThemeProvider defaultBrand: 런타임에 setBrand · setTheme 를 쓸 수 있게 합니다(마크업이 defaultBrand 보다 앞섬, theme 1.7.0 이상)
 */
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="ko" data-brand="ontology" suppressHydrationWarning>
      <body className="bg-background text-foreground antialiased">
        <ThemeProvider defaultTheme="light" defaultBrand="ontology">
          <AppShell>{children}</AppShell>
        </ThemeProvider>
      </body>
    </html>
  )
}

import Link from 'next/link'
import { ArrowLeft, ChevronLeft, ChevronRight } from 'lucide-react'
import { Button } from '@axis-ds/ui-react/button'

interface DetailHeadProps {
  backHref: string
  backLabel: string
  title: string
  subtitle?: string
  lead?: React.ReactNode
  badges?: React.ReactNode
  prevHref?: string
  nextHref?: string
}

/**
 * depth 상세 머리: 뒤로 · (타일) · 제목 · 이전 · 다음.
 * 브레드크럼 대신 뒤로 버튼 하나로 목록에 돌아갑니다.
 */
export function DetailHead({ backHref, backLabel, title, subtitle, lead, badges, prevHref, nextHref }: DetailHeadProps) {
  return (
    <div className="mb-[18px] flex items-start gap-3">
      <Button asChild variant="ghost" size="icon" className="-ml-2 shrink-0">
        <Link href={backHref} aria-label={backLabel}>
          <ArrowLeft aria-hidden className="size-5" />
        </Link>
      </Button>
      {lead}
      <div className="min-w-0 flex-1">
        <h1 className="flex flex-wrap items-center gap-2 text-2xl font-bold leading-snug tracking-tight">
          {title}
          {badges}
        </h1>
        {subtitle && <p className="mt-1 text-[13.5px] text-muted-foreground">{subtitle}</p>}
      </div>
      <div className="flex shrink-0 items-center gap-2">
        <PagerLink href={prevHref} label="이전" icon="prev" />
        <PagerLink href={nextHref} label="다음" icon="next" />
      </div>
    </div>
  )
}

function PagerLink({ href, label, icon }: { href?: string; label: string; icon: 'prev' | 'next' }) {
  const content = (
    <>
      {icon === 'prev' && <ChevronLeft aria-hidden className="size-4" />}
      {label}
      {icon === 'next' && <ChevronRight aria-hidden className="size-4" />}
    </>
  )
  if (!href) {
    return (
      <Button variant="outline" size="sm" disabled className="gap-1">
        {content}
      </Button>
    )
  }
  return (
    <Button asChild variant="outline" size="sm" className="gap-1">
      <Link href={href}>{content}</Link>
    </Button>
  )
}

import { Box, Braces, Link2, Zap, type LucideIcon } from 'lucide-react'
import { cn } from '../../lib/utils'
import { kindLabels, type ElementKind } from '../../lib/demo-data'

const icons: Record<ElementKind, LucideIcon> = {
  entity: Box,
  relation: Link2,
  logic: Braces,
  action: Zap,
}

const sizes = {
  sm: 'size-7 rounded-[7px] [&_svg]:size-[15px]',
  md: 'size-10 rounded-[10px] [&_svg]:size-[22px]',
  lg: 'size-[52px] rounded-[13px] [&_svg]:size-7',
}

/** 요소 타일: 색은 회색 하나, 종류는 아이콘으로만 구분합니다(프로토타입 v0.24 이후 규칙) */
export function ElementTile({ kind, size = 'md' }: { kind: ElementKind; size?: keyof typeof sizes }) {
  const Icon = icons[kind]
  return (
    <span
      title={kindLabels[kind]}
      className={cn('inline-flex shrink-0 items-center justify-center bg-secondary text-secondary-foreground', sizes[size])}
    >
      <Icon aria-hidden />
      <span className="sr-only">{kindLabels[kind]}</span>
    </span>
  )
}

'use client'

import { useMemo, useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { Search } from 'lucide-react'
import { Input } from '@axis-ds/ui-react/input'
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@axis-ds/ui-react/table'
import { cn } from '../../lib/utils'
import { elements, kindLabels, type ElementKind } from '../../lib/demo-data'
import { ElementTile } from './element-tile'
import { StatusBadge } from './status-badge'

const kinds: (ElementKind | 'all')[] = ['all', 'entity', 'relation', 'logic', 'action']

/** 필터 칩: 고르면 연한 키컬러 바탕 · 키컬러 테두리 */
function FilterChip({ on, onClick, children }: { on: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      aria-pressed={on}
      onClick={onClick}
      className={cn(
        'inline-flex h-9 items-center rounded-full border border-input bg-card px-3.5 text-[13px] text-foreground hover:border-foreground',
        on && 'border-primary bg-accent font-semibold text-accent-foreground hover:border-primary'
      )}
    >
      {children}
    </button>
  )
}

/**
 * 목록 도구줄(검색 + 필터 칩) + 표. 줄을 누르면 depth 상세로 이동합니다(시트로 열지 않음).
 * 키보드 사용자는 이름 칸의 링크로 같은 곳에 갑니다.
 */
export function EntityList() {
  const router = useRouter()
  const [query, setQuery] = useState('')
  const [kind, setKind] = useState<ElementKind | 'all'>('all')

  const rows = useMemo(() => {
    const q = query.trim().toLowerCase()
    return elements.filter(
      (e) =>
        (kind === 'all' || e.kind === kind) &&
        (q === '' || e.name.toLowerCase().includes(q) || e.nameEn.toLowerCase().includes(q))
    )
  }, [query, kind])

  return (
    <>
      <div role="search" className="mb-3 flex flex-wrap items-center gap-2">
        <div className="relative w-[300px] max-w-full">
          <Search aria-hidden className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            type="search"
            aria-label="요소 검색"
            placeholder="이름으로 찾기"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-9"
          />
        </div>
        <div role="group" aria-label="종류" className="flex flex-wrap items-center gap-2">
          {kinds.map((k) => (
            <FilterChip key={k} on={kind === k} onClick={() => setKind(k)}>
              {k === 'all' ? '전체' : kindLabels[k]}
            </FilterChip>
          ))}
        </div>
      </div>

      <div className="overflow-hidden rounded-sm border">
        <Table>
          <TableHeader>
            <TableRow className="bg-muted hover:bg-muted">
              <TableHead>이름</TableHead>
              <TableHead>종류</TableHead>
              <TableHead>상태</TableHead>
              <TableHead>담당</TableHead>
              <TableHead className="text-right">수정일</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} className="py-8 text-center text-muted-foreground">
                  조건에 맞는 요소가 없어요
                </TableCell>
              </TableRow>
            ) : (
              rows.map((e) => (
                <TableRow
                  key={e.id}
                  onClick={() => router.push(`/entities/${e.id}`)}
                  className="cursor-pointer hover:bg-muted"
                >
                  <TableCell>
                    <div className="flex items-center gap-2.5">
                      <ElementTile kind={e.kind} size="sm" />
                      <Link
                        href={`/entities/${e.id}`}
                        onClick={(ev) => ev.stopPropagation()}
                        className="font-semibold hover:underline"
                      >
                        {e.name}
                      </Link>
                      <span className="text-[12.5px] text-muted-foreground">{e.nameEn}</span>
                    </div>
                  </TableCell>
                  <TableCell>{kindLabels[e.kind]}</TableCell>
                  <TableCell>
                    <StatusBadge status={e.status} />
                  </TableCell>
                  <TableCell>{e.owner}</TableCell>
                  <TableCell className="text-right tabular-nums">{e.updatedAt}</TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>
    </>
  )
}

interface ListHeadProps {
  title: string
  count?: number
  description?: string
  tools?: React.ReactNode
}

/** 목록 머리: 제목 · 개수 · 설명 + 오른쪽 동작. 메뉴의 첫 화면은 이 머리를 가진 목록 페이지입니다 */
export function ListHead({ title, count, description, tools }: ListHeadProps) {
  return (
    <div className="mb-[18px] flex items-start gap-4">
      <div className="min-w-0 flex-1">
        <h1 className="flex flex-wrap items-center gap-2 text-2xl font-bold leading-snug tracking-tight">
          {title}
          {count !== undefined && (
            <span className="rounded-full bg-secondary px-2.5 py-px text-[13px] font-bold text-secondary-foreground">
              {count}
            </span>
          )}
        </h1>
        {description && <p className="mt-1 text-[13.5px] text-muted-foreground">{description}</p>}
      </div>
      {tools && <div className="flex shrink-0 items-center gap-2">{tools}</div>}
    </div>
  )
}

import { Card } from '@axis-ds/ui-react/card'
import { cn } from '../../lib/utils'

interface PageFrameProps {
  children: React.ReactNode
  /** 오른쪽 보조 상자(통합 뷰의 「확인 필요」 등). 있으면 본문 카드가 그만큼 줄어듭니다 */
  aside?: React.ReactNode
  /** 본문 카드 안 여백을 없앱니다(2분할처럼 카드 안을 직접 나누는 화면) */
  fill?: boolean
}

/**
 * 콘텐츠 카드 한 장(+ 선택적 보조 상자 420px).
 * 카드는 AXIS Card 를 그대로 씁니다. ontology 브랜드에서 둥글기 12px(--axis-radius-surface) · 그림자 없음(--axis-card-shadow)이라
 * 템플릿이 따로 그림자나 둥글기를 정하지 않습니다. 1199px 이하에서는 보조 상자가 카드 아래로 내려가 1열이 됩니다.
 */
export function PageFrame({ children, aside, fill }: PageFrameProps) {
  return (
    <div className="flex min-h-0 flex-1 gap-2.5 max-[1199px]:flex-col max-[1199px]:overflow-y-auto">
      <Card
        data-ontology-card=""
        className={cn(
          'flex min-h-0 min-w-0 flex-1 flex-col overflow-y-auto max-[1199px]:flex-none max-[1199px]:overflow-visible',
          !fill && 'px-[26px] pb-[30px] pt-6 max-[1199px]:px-5 max-[1199px]:pb-[26px] max-[1199px]:pt-5'
        )}
      >
        {children}
      </Card>
      {aside}
    </div>
  )
}

/** 보조 상자: 머리 52px + 스크롤되는 본문. 폭 420px, 1199px 이하에서는 카드 아래 전체 폭 */
export function AsideBox({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <Card
      data-ontology-aside=""
      className="flex min-h-0 w-[420px] shrink-0 flex-col overflow-hidden max-[1199px]:w-full max-[1199px]:flex-none"
    >
      <h2 className="flex h-[52px] shrink-0 items-center border-b px-3.5 text-[15px] font-bold">{title}</h2>
      <div className="flex min-h-0 flex-1 flex-col overflow-y-auto px-4 pb-4 pt-3.5">{children}</div>
    </Card>
  )
}

interface SectionProps {
  title: string
  count?: number
  children: React.ReactNode
}

/** 절(중제목 + 내용): 밑줄 없이 간격으로 나눕니다. 절 사이 40px, 제목과 내용 사이 14px */
export function Section({ title, count, children }: SectionProps) {
  return (
    <section className="mb-10 last:mb-2">
      <h2 className="mb-3.5 flex items-center gap-2.5 text-base font-bold">
        {title}
        {count !== undefined && <span className="text-[13px] font-semibold text-muted-foreground">{count}</span>}
      </h2>
      {children}
    </section>
  )
}

/** 설명 목록(이름 110px + 값) */
export function KeyValue({ items }: { items: { label: string; value: React.ReactNode }[] }) {
  return (
    <dl className="grid grid-cols-[110px_minmax(0,1fr)] gap-x-4 gap-y-2.5 text-sm">
      {items.map((it) => (
        <div key={it.label} className="contents">
          <dt className="text-muted-foreground">{it.label}</dt>
          <dd className="min-w-0">{it.value}</dd>
        </div>
      ))}
    </dl>
  )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { Boxes, ChevronDown, FolderKanban, LayoutDashboard, type LucideIcon } from 'lucide-react'
import { cn } from '../../lib/utils'
import { projects, workspace } from '../../lib/demo-data'
import { ThemeToggle } from './theme-toggle'

interface NavLink {
  href: string
  label: string
}

interface NavGroup {
  id: string
  label: string
  icon: LucideIcon
  items: NavLink[]
}

const groups: NavGroup[] = [
  { id: 'ontology', label: '온톨로지', icon: Boxes, items: [{ href: '/entities', label: '요소 목록' }] },
  {
    id: 'projects',
    label: '프로젝트',
    icon: FolderKanban,
    items: projects.map((p) => ({ href: `/projects/${p.id}`, label: p.name })),
  },
]

function isActive(pathname: string, href: string) {
  return href === '/' ? pathname === '/' : pathname === href || pathname.startsWith(`${href}/`)
}

/**
 * 사이드바: 워크스페이스 이름 · 대메뉴(한 번에 하나만 펼침) · 하위 메뉴 · 화면 모드 전환.
 * 고른 메뉴는 연한 키컬러 바탕 + 진한 키컬러 글자(accent · accent-foreground)로 표시합니다.
 */
export function Sidebar() {
  const pathname = usePathname() ?? '/'
  const current = groups.find((g) => g.items.some((i) => isActive(pathname, i.href)))?.id
  const [open, setOpen] = useState<string | undefined>(current ?? groups[0].id)

  return (
    <nav aria-label="주 메뉴" className="flex min-h-0 flex-col overflow-hidden pb-3 pl-[18px] pr-2.5 pt-3.5">
      <div className="px-1.5 pb-[18px] pt-1">
        <p className="text-base font-extrabold tracking-tight">{workspace.name}</p>
        <p className="mt-px text-[12.5px] text-muted-foreground">{workspace.role}</p>
      </div>

      <ul className="flex min-h-0 flex-col gap-1.5 overflow-y-auto">
        <li>
          <Link
            href="/"
            aria-current={pathname === '/' ? 'page' : undefined}
            className={cn(
              'flex items-center gap-2.5 rounded-sm px-3 py-2.5 text-[15px] font-medium hover:bg-secondary',
              pathname === '/' && 'bg-accent font-semibold text-accent-foreground hover:bg-accent'
            )}
          >
            <LayoutDashboard aria-hidden className="size-[18px] shrink-0" />
            통합 뷰
          </Link>
        </li>
        {groups.map((g) => {
          const expanded = open === g.id
          const Icon = g.icon
          return (
            <li key={g.id}>
              <button
                type="button"
                aria-expanded={expanded}
                aria-controls={`nav-${g.id}`}
                onClick={() => setOpen(expanded ? undefined : g.id)}
                className={cn(
                  'flex w-full items-center gap-2.5 rounded-sm px-3 py-2.5 text-left text-[15px] font-medium hover:bg-secondary',
                  current === g.id && 'font-semibold'
                )}
              >
                <Icon aria-hidden className="size-[18px] shrink-0 text-muted-foreground" />
                <span className="min-w-0 flex-1 truncate">{g.label}</span>
                <ChevronDown
                  aria-hidden
                  className={cn('size-3.5 text-muted-foreground transition-transform', expanded && 'rotate-180')}
                />
              </button>
              <ul id={`nav-${g.id}`} hidden={!expanded} className="flex flex-col gap-0.5 pb-2.5 pl-3.5 pt-1">
                {g.items.map((item) => {
                  const active = isActive(pathname, item.href)
                  return (
                    <li key={item.href}>
                      <Link
                        href={item.href}
                        aria-current={active ? 'page' : undefined}
                        className={cn(
                          'block truncate rounded-sm px-3 py-2 text-[14.5px] hover:bg-secondary',
                          active && 'bg-accent font-semibold text-accent-foreground hover:bg-accent'
                        )}
                      >
                        {item.label}
                      </Link>
                    </li>
                  )
                })}
              </ul>
            </li>
          )
        })}
      </ul>

      <div className="mt-auto border-t pt-3">
        <ThemeToggle />
      </div>
    </nav>
  )
}

interface SplitPaneProps {
  left: React.ReactNode
  children: React.ReactNode
}

/**
 * 카드 안 좌우 분할: 왼쪽 열 300px + 1px 중립 선 + 오른쪽 본문(프로토타입 v0.28 `.o-split`).
 * 선은 기본 테두리색(--border)이라 「한쪽 색 선」이 아닙니다. 1199px 이하에서는 1열로 쌓이고 선은 아래쪽으로 바뀝니다.
 */
export function SplitPane({ left, children }: SplitPaneProps) {
  return (
    <div
      data-ontology-split=""
      className="grid min-h-0 flex-1 grid-cols-[300px_minmax(0,1fr)] grid-rows-[minmax(0,1fr)] max-[1199px]:grid-cols-1 max-[1199px]:grid-rows-none"
    >
